# Request demos - check if they're available now
import re

def load_detailed():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    jnl_path = d + '/../jsonl/' + os.path.basename(d) + '.jsonl'
    try:
        with open(jnl_path) as f:
            content = f.read()
    except:
        return [], None

    # Parse for demo pairs
    pairs = []
    in_grid = False
    current_key = None
    current_grid = []

    for line in content.split('\n'):
        line = line.strip()
        if line.startswith('Demo pair') or line.startswith('Test input'):
            if current_key and current_grid:
                pairs.append((current_key, current_grid))
            in_grid = True
            match = re.match(r'(\w+)\s+(\d+)x(\d+)', line)
            if match:
                current_key = match.group(1)
        elif in_grid and line:
            if current_grid is None:
                current_grid = []
            current_grid.append([int(x) for x in line.split()])

    if current_key and current_grid:
        pairs.append((current_key, current_grid))

    return pairs, d

pairs, d = load_detailed()
print(f"Found {len(pairs)} pairs")
for key, grid in pairs:
    print(f"{key}: {grid}")

